#include "core/notification_service.h"
#include "core/database.h"
namespace pos { NotificationService::NotificationService(std::shared_ptr<Database> database):db_(std::move(database)){} QString NotificationService::create(const QString& type,const QString& title,const QString& body){if(type.trimmed().isEmpty()||title.trimmed().isEmpty()||body.trimmed().isEmpty())throw DatabaseError("notification fields are required");Transaction tx(db_->handle());const auto id=uuid();auto q=db_->prepare("INSERT INTO notifications(id,type,title,body,is_read,created_at) VALUES(?,?,?, ?,0,?)");q.bind(1,id);q.bind(2,type.trimmed());q.bind(3,title.trimmed());q.bind(4,body.trimmed());q.bind(5,utcNow());q.execute();tx.commit();return id;} QList<Notification> NotificationService::unread(int limit)const{if(limit<1||limit>1000)throw DatabaseError("invalid notification limit");QList<Notification> result;auto q=db_->prepare("SELECT id,type,title,body,created_at,is_read FROM notifications WHERE is_read=0 ORDER BY created_at DESC LIMIT ?");q.bind(1,limit);while(q.stepRow())result.append({q.text(0),q.text(1),q.text(2),q.text(3),q.text(4),q.integer(5)!=0});return result;} void NotificationService::markRead(const QString& id){Transaction tx(db_->handle());auto q=db_->prepare("UPDATE notifications SET is_read=1 WHERE id=? AND is_read=0");q.bind(1,id);q.execute();if(sqlite3_changes(db_->handle())!=1)throw DatabaseError("notification not found or already read");tx.commit();} }
